# -*- coding: utf-8 -*-
"""
ai_filter.py — оставляет от ИИ-разбора только то, что нужно карточке.

Ставится поверх ai.py, сам ai.py не трогается.

Что делает:
    · в чат выводит ТОЛЬКО поля карточки — марка, модель, год, VIN, пробег,
      объём, топливо, КПП, привод, цвет, техсостояние
    · выбрасывает аукцион, лот, аукционный балл, дату покупки, предоплату,
      задолженность, проценты оплаты, комплектацию, вес, двери, места,
      «Дополнительно», «Проверку» и любые догадки
    · деньги из разбора не берёт вообще — суммы вводит владелец руками
    · чего нет в источнике — оставляет пустым, вариантов не предлагает
    · VIN — ключ: новый VIN закрывает текущую карточку и открывает новую,
      знакомый VIN дополняет существующую
"""

import json
import logging
import re
import re as _re
from datetime import date, datetime

from telegram import InlineKeyboardButton, InlineKeyboardMarkup, Update
from telegram.ext import ApplicationHandlerStop, CallbackQueryHandler, ContextTypes

import cars_schema as S
import db

log = logging.getLogger(__name__)

# ─────────────────────────────────────────────────────────────
# ЧТО ВООБЩЕ ПУСКАЕМ В КАРТОЧКУ
# ─────────────────────────────────────────────────────────────
# ключ карточки -> возможные имена в разборе
ALLOWED = {
    "brand": ("brand", "make", "manufacturer", "марка", "производитель"),
    "model": ("model", "model_name", "модель"),
    "year": ("year", "registration_date", "reg_date", "год", "год_выпуска"),
    "vin": ("vin", "vin_code", "chassis", "chassis_no", "chassis_number", "вин",
            "номер_кузова"),
    "fuel": ("fuel", "fuel_type", "топливо", "тип_топлива"),
    "engine_cc": ("engine_cc", "engine", "engine_size", "engine_size_cc",
                  "engine_volume", "displacement", "объем", "объём", "двигатель"),
    "gearbox": ("gearbox", "transmission", "коробка", "кпп", "коробка_передач"),
    "drive": ("drive", "drivetrain", "drive_type", "привод"),
    "mileage_km": ("mileage_km", "mileage", "odometer", "пробег"),
    "color": ("color", "colour", "цвет"),
    "condition_text": ("condition_text", "condition", "состояние",
                       "tech_condition", "техническое_состояние"),
}
LABELS = {
    "brand": "Марка", "model": "Модель", "year": "Год", "vin": "VIN",
    "fuel": "Топливо", "engine_cc": "Объём", "gearbox": "КПП", "drive": "Привод",
    "mileage_km": "Пробег", "color": "Цвет", "condition_text": "Тех. состояние",
}
ORDER = ["brand", "model", "year", "vin", "fuel", "engine_cc", "gearbox",
         "drive", "mileage_km", "color", "condition_text"]

# перевод значений на русский. Чего нет в словаре — не переводим и не выдумываем.
FUEL = {"gasoline": "бензин", "petrol": "бензин", "gas": "бензин", "diesel": "дизель",
        "hybrid": "гибрид", "electric": "электро", "ev": "электро", "lpg": "газ",
        "бензин": "бензин", "дизель": "дизель", "гибрид": "гибрид", "電気": "электро"}
GEARBOX = {"automatic": "автомат", "auto": "автомат", "at": "автомат",
           "manual": "механика", "mt": "механика", "cvt": "вариатор",
           "dct": "робот", "dsg": "робот",
           "автомат": "автомат", "механика": "механика"}
DRIVE = {"awd": "полный", "4wd": "полный", "4x4": "полный",
         "fwd": "передний", "ff": "передний",
         "rwd": "задний", "fr": "задний",
         "полный": "полный", "передний": "передний", "задний": "задний"}
COLOR = {"white": "белый", "black": "чёрный", "silver": "серебристый",
         "grey": "серый", "gray": "серый", "blue": "синий", "red": "красный",
         "green": "зелёный", "beige": "бежевый", "brown": "коричневый",
         "білий": "белый", "чорний": "чёрный", "сірий": "серый",
         "синій": "синий", "червоний": "красный", "зелений": "зелёный"}


def _norm(key):
    return str(key).strip().lower().replace(" ", "_").replace("-", "_").replace(".", "")


# служебные ветки разбора — в карточку не идут никогда
SKIP = {"_meta", "meta", "question", "summary", "note", "extra", "raw",
        "источник", "source", "model_name_ai"}


def flatten(obj, out=None):
    """Разворачивает разбор в один уровень.
    Понимает вид {"поле": {"value": ..., "sure": true}} и пропускает
    всё, в чём ИИ не уверен (sure: false) — догадки в карточку не идут."""
    if out is None:
        out = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            nk = _norm(k)
            if nk in SKIP:
                continue
            if isinstance(v, dict) and "value" in v:
                if v.get("sure") is False:
                    continue
                val = v.get("value")
                if val not in (None, "", "-", "—") and nk not in out:
                    out[nk] = val
                continue
            if isinstance(v, (dict, list)):
                flatten(v, out)
            elif v not in (None, "", "-", "—"):
                if nk not in out:
                    out[nk] = v
    elif isinstance(obj, list):
        for item in obj:
            flatten(item, out)
    return out


def _pick(flat, keys):
    for k in keys:
        nk = _norm(k)
        if flat.get(nk) not in (None, "", "-", "—"):
            return flat[nk]
    for nk, value in flat.items():
        for k in keys:
            if _norm(k) in nk and value not in (None, "", "-", "—"):
                return value
    return None


def _all_text(flat):
    return " | ".join(str(v) for v in flat.values() if v not in (None, ""))


# запасной поиск прямо по тексту разбора, если поле названо непривычно
FALLBACK = [
    ("vin", _re.compile(r"\b[A-HJ-NPR-Z0-9]{17}\b")),
    ("engine_cc", _re.compile(r"([\d,\.]{3,7})\s*(?:cc|см3|см³)", _re.I)),
    ("mileage_km", _re.compile(r"([\d,\s]{3,12})\s*(?:km|км)", _re.I)),
    ("fuel", _re.compile(r"\b(diesel|gasoline|petrol|hybrid|electric|бензин|дизель)\b", _re.I)),
    ("gearbox", _re.compile(r"\b(automatic|manual|cvt|dct|автомат|механика)\b", _re.I)),
    ("color", _re.compile(r"\b(white|black|silver|grey|gray|blue|red|green|beige|brown)\b", _re.I)),
    ("year", _re.compile(r"\b(19[89]\d|20[0-3]\d)\b")),
]


def _cc(value):
    """В кубические сантиметры. Непонятно — None, догадок не делаем."""
    if value in (None, ""):
        return None
    txt = str(value).lower().replace(",", ".")
    nums = re.findall(r"\d+(?:\.\d+)?", txt)
    if not nums:
        return None
    n = float(nums[0])
    if n < 20:
        return int(round(n * 1000))
    if 100 <= n <= 9000:
        return int(n)
    return None


def _km(value):
    if value in (None, ""):
        return None
    txt = str(value).lower().replace("\u00a0", " ")
    digits = "".join(ch for ch in txt.replace(" ", "") if ch.isdigit())
    if not digits:
        return None
    n = int(digits)
    if "тыс" in txt and n < 1000:
        n *= 1000
    return n


def _year(value):
    if value in (None, ""):
        return None
    m = re.search(r"(19|20)\d{2}", str(value))
    return int(m.group(0)) if m else None


def _map(value, table):
    if value in (None, ""):
        return None
    key = str(value).strip().lower()
    return table.get(key, str(value).strip())


def _log_parsed(parsed, data):
    """Пишет последние разборы в parsed_log.json — чтобы видеть,
    что именно вернул ИИ и что из этого попало в карточку."""
    try:
        import os
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                            "parsed_log.json")
        old = []
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                old = json.load(f)
        old.insert(0, {
            "когда": datetime.now().strftime("%d.%m %H:%M"),
            "что вернул ИИ": parsed,
            "что взято в карточку": data,
        })
        with open(path, "w", encoding="utf-8") as f:
            json.dump(old[:5], f, ensure_ascii=False, indent=2)
    except Exception as e:
        log.warning("parsed_log: %s", e)


def clean(parsed, extra_text=""):
    """Из разбора оставляем только поля карточки.
    extra_text — исходное сообщение: если разбор что-то потерял, ищем там."""
    flat = flatten(parsed if isinstance(parsed, dict) else {})
    text_all = _all_text(flat)
    if extra_text:
        text_all = text_all + " | " + str(extra_text)
    out = {}
    for field, keys in ALLOWED.items():
        raw = _pick(flat, keys)
        if raw in (None, "", "-", "—"):
            for f2, rx in FALLBACK:
                if f2 != field:
                    continue
                m = rx.search(text_all)
                if m:
                    raw = m.group(1) if m.groups() else m.group(0)
                    break
        if raw in (None, ""):
            continue
        if field == "engine_cc":
            val = _cc(raw)
            if val and not (500 <= val <= 8000):
                val = None
        elif field == "mileage_km":
            val = _km(raw)
            if val and not (0 < val <= 2000000):
                val = None
        elif field == "year":
            val = _year(raw)
            if val and not (1980 <= val <= date.today().year + 1):
                val = None
        elif field == "fuel":
            val = _map(raw, FUEL)
        elif field == "gearbox":
            val = _map(raw, GEARBOX)
        elif field == "drive":
            val = _map(raw, DRIVE)
        elif field == "color":
            val = _map(raw, COLOR)
        elif field == "vin":
            vin = str(raw).upper().replace(" ", "").replace("-", "")
            if len(vin) != 17:
                m = _re.search(r"[A-HJ-NPR-Z0-9]{17}", text_all.upper())
                vin = m.group(0) if m else None
            val = vin
        else:
            val = str(raw).strip()
        if val not in (None, ""):
            out[field] = val
    _log_parsed(parsed, out)
    return out


def find_by_vin(vin):
    if not vin:
        return None
    with db.connect() as c:
        row = c.execute("SELECT * FROM cars WHERE UPPER(vin)=? ORDER BY id DESC LIMIT 1",
                        (vin.upper(),)).fetchone()
    return dict(row) if row else None


# ─────────────────────────────────────────────────────────────
# ВЫВОД В ЧАТ
# ─────────────────────────────────────────────────────────────

def render(data, existing=None):
    L = ["<b>Автомобиль</b>"]
    if existing:
        L.append("VIN уже есть в базе: <b>%s</b>" % (existing.get("auto_number") or
                                                     "#%s" % existing["id"]))
        L.append("Дополню эту карточку, новую заводить не буду.")
    L.append("")
    for field in ORDER:
        val = data.get(field)
        if val in (None, ""):
            continue
        if field == "engine_cc":
            val = S.num(val, " см³")
        elif field == "mileage_km":
            val = S.num(val, " км")
        L.append("<b>%s:</b> %s" % (LABELS[field], val))

    return "\n".join(L)


# ─────────────────────────────────────────────────────────────
# ПОДМЕНА ФУНКЦИЙ ai.py
# ─────────────────────────────────────────────────────────────

_ORIG_DRAFT = None
_ORIG_REVIEW = None
_ORIG_DATA = None


def source_text(inbox_id):
    """Текст исходного сообщения — из него добираем то, что разбор потерял."""
    if not inbox_id:
        return ""
    try:
        zapis = db.get_inbox(inbox_id)
        return (zapis or {}).get("text") or ""
    except Exception:
        return ""


def render_from(parsed, issues=None):
    """Прямая точка входа для team_bot: только поля карточки, ничего лишнего."""
    if not isinstance(parsed, dict) or parsed.get("type") == "client":
        if _ORIG_DRAFT:
            try:
                return _ORIG_DRAFT(parsed, issues)
            except Exception:
                pass
        return ""
    data = clean(parsed)
    return render(data, find_by_vin(data.get("vin")))


def install():
    global _ORIG_DRAFT, _ORIG_REVIEW, _ORIG_DATA
    """Перехватывает вывод разбора: лишнее не доходит ни до чата, ни до базы."""
    try:
        import ai
    except Exception as e:
        log.warning("ai.py не найден, фильтр не поставлен: %s", e)
        return

    def render_draft(parsed, issues=None, *a, **k):
        if isinstance(parsed, dict) and parsed.get("type") == "client":
            return _orig_draft(parsed, issues) if _orig_draft else ""
        data = clean(parsed if isinstance(parsed, dict) else {})
        existing = find_by_vin(data.get("vin"))
        return render(data, existing)

    def render_review(*a, **k):
        return ""      # блок «Проверка» и предположения в чат не выводим

    def to_card_data(parsed, *a, **k):
        if isinstance(parsed, dict) and parsed.get("type") == "client":
            return _orig_data(parsed) if _orig_data else {}
        data = clean(parsed if isinstance(parsed, dict) else {})
        # в старые колонки кладём то, что понимает db.create_card
        out = {}
        for k2, v in data.items():
            if k2 == "engine_cc":
                out["engine"] = v
            elif k2 == "mileage_km":
                out["mileage"] = v
            elif k2 == "condition_text":
                out["condition"] = v
            else:
                out[k2] = v
        out["_clean"] = data          # новые поля дозапишем после создания
        return out

    _orig_draft = getattr(ai, "render_draft", None)
    _orig_data = getattr(ai, "to_card_data", None)
    _ORIG_DRAFT = _orig_draft
    _ORIG_REVIEW = getattr(ai, "render_review", None)
    _ORIG_DATA = _orig_data
    ai.render_draft = render_draft
    ai.render_review = render_review
    ai.to_card_data = to_card_data
    log.info("ai_filter поставлен: в карточку идут только нужные поля")


# ─────────────────────────────────────────────────────────────
# СОХРАНЕНИЕ: VIN РЕШАЕТ, НОВАЯ КАРТОЧКА ИЛИ СТАРАЯ
# ─────────────────────────────────────────────────────────────


def store(data, actor, inbox_id=None, card_id=None):
    """Кладёт данные в карточку.
    Новая карточка заводится ТОЛЬКО когда есть VIN.
    Заполненные поля никогда не затираются — дописываются лишь пустые.
    Возвращает (card_id, номер, признак новой) или (None, None, None),
    если заводить нечего.
    """
    existing = None
    if card_id:
        existing = db.get_card("cars", int(card_id))
    if not existing and data.get("vin"):
        existing = find_by_vin(data["vin"])

    if existing:
        card_id = existing["id"]
        for field, value in data.items():
            if existing.get(field) in (None, "", 0):
                db.update_card_field("cars", card_id, field, value, actor)
        number = existing.get("auto_number")
        if not number:
            with db.connect() as c:
                number = S.next_auto_number(c)
            db.update_card_field("cars", card_id, "auto_number", number, actor)
        novaya = False
    else:
        if not data.get("vin"):
            return None, None, None          # без VIN новую не заводим
        legacy = {k: v for k, v in {
            "brand": data.get("brand"), "model": data.get("model"),
            "year": data.get("year"), "vin": data.get("vin"),
            "fuel": data.get("fuel"), "color": data.get("color"),
        }.items() if v}
        card_id = db.create_card("cars", legacy, actor)
        with db.connect() as c:
            number = S.next_auto_number(c)
        db.update_card_field("cars", card_id, "auto_number", number, actor)
        for field, value in data.items():
            db.update_card_field("cars", card_id, field, value, actor)
        db.set_card_review("cars", card_id, db.ST_APPROVED_OWNER, actor, publish=False)
        novaya = True

    if inbox_id:
        # Присланное сообщение к карточке не прикрепляем: скриншоты и документы
        # в галерею попадать не должны. Фото добавляются только кнопкой.
        try:
            db.link_inbox_card(inbox_id, "cars", card_id, actor)
            db.set_inbox_status(inbox_id, db.ST_APPROVED_OWNER, actor)
        except Exception:
            pass

    return card_id, number, novaya


async def autosave(update, context, thinking, inbox_id, parsed):
    """Сохраняет авто сразу, без кнопки подтверждения.
    Возвращает True, если карточка записана."""
    if not isinstance(parsed, dict) or parsed.get("type") != "car":
        return False
    user = update.effective_user
    staff = db.get_staff(user.id) if user else None
    if not staff:
        return False
    text_prosby = source_text(inbox_id)
    try:
        import assistant
        if assistant.is_request(text_prosby):
            card = None
            posl = context.user_data.get("car_last")
            if posl:
                card = db.get_card("cars", posl)
            otvet = assistant.ask(text_prosby, card)
            if otvet:
                await thinking.edit_text(assistant.clean_html(otvet)[:3800],
                                         parse_mode="HTML")
                context.user_data.pop("ai_draft", None)
                return True
    except Exception as e:
        log.warning("Помощник: %s", e)

    data = clean(parsed, source_text(inbox_id))
    if not data:
        return False

    otkrytaya = context.user_data.get("car_last")
    try:
        card_id, number, novaya = store(data, staff["user_id"], inbox_id,
                                        card_id=None if data.get("vin") else otkrytaya)
    except Exception as e:
        log.warning("Автосохранение не прошло: %s", e)
        return False

    if not card_id:
        # VIN не найден и открытой карточки нет — новую не заводим
        kb = []
        posledn = None
        try:
            spisok = db.list_cards("cars", limit=1)
            posledn = spisok[0] if spisok else None
        except Exception:
            pass
        if posledn:
            kb.append([InlineKeyboardButton(
                "Записать в %s" % (posledn.get("auto_number") or "последнюю"),
                callback_data="car_open:%d" % posledn["id"])])
        kb.append([InlineKeyboardButton("Список автомобилей",
                                        callback_data="cars_cards")])
        try:
            await thinking.edit_text(
                "Новую карточку завожу только по VIN — его в сообщении нет.\n"
                "Пришлите VIN или откройте нужную карточку.",
                reply_markup=InlineKeyboardMarkup(kb))
        except Exception:
            pass
        return True

    head = ("Открыл новую карточку %s" % number if novaya
            else "Дополнил карточку %s — заполненное не тронул" % number)
    text = head + "\n\n" + render(data)
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("← Открыть карточку", callback_data="car_open:%d" % card_id)],
        [InlineKeyboardButton("Редактировать", callback_data="car_edit:%d" % card_id),
         InlineKeyboardButton("Фото и видео", callback_data="car_media:%d" % card_id)],
    ])
    try:
        await thinking.edit_text(text, parse_mode="HTML", reply_markup=kb)
    except Exception:
        await update.effective_message.reply_text(text, parse_mode="HTML",
                                                  reply_markup=kb)
    context.user_data.pop("ai_draft", None)
    context.user_data["car_last"] = card_id
    return True

async def save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    staff = db.get_staff(q.from_user.id)
    draft = context.user_data.get("ai_draft")
    if not draft or not staff:
        return                      # пусть отработает обычный обработчик

    parsed = draft.get("parsed") or {}
    if parsed.get("type") == "client":
        return                      # клиентов не трогаем

    data = clean(parsed)
    if not data:
        await q.message.reply_text("Из сообщения нечего взять в карточку.")
        raise ApplicationHandlerStop

    existing = find_by_vin(data.get("vin"))
    actor = staff["user_id"]

    if existing:
        card_id = existing["id"]
        for field, value in data.items():
            if not existing.get(field):
                db.update_card_field("cars", card_id, field, value, actor)
        note = "Дополнил карточку %s." % (existing.get("auto_number") or "#%d" % card_id)
    else:
        legacy = {"brand": data.get("brand"), "model": data.get("model"),
                  "year": data.get("year"), "vin": data.get("vin"),
                  "fuel": data.get("fuel"), "color": data.get("color")}
        legacy = {k: v for k, v in legacy.items() if v}
        card_id = db.create_card("cars", legacy, actor)
        with db.connect() as c:
            number = S.next_auto_number(c)
        db.update_card_field("cars", card_id, "auto_number", number, actor)
        for field, value in data.items():
            db.update_card_field("cars", card_id, field, value, actor)
        db.set_card_review("cars", card_id, db.ST_APPROVED_OWNER, actor, publish=False)
        note = "Открыл новую карточку %s." % number

    # Источник распознавания остаётся во входящих; переносим только видео.
    try:
        import team_bot
        video = team_bot.collect_media(draft["inbox_id"])[1]
        if video:
            db.update_card_field("cars", card_id, "video_h", video[0], actor)
    except Exception as e:
        log.warning("Медиа не перенеслись: %s", e)

    try:
        db.link_inbox_card(draft["inbox_id"], "cars", card_id, actor)
        db.set_inbox_status(draft["inbox_id"], db.ST_APPROVED_OWNER, actor)
    except Exception:
        pass

    context.user_data.pop("ai_draft", None)
    card = db.get_card("cars", card_id)
    await q.message.edit_reply_markup(reply_markup=None)
    await q.message.reply_text(
        note,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("Открыть карточку", callback_data="car_open:%d" % card_id)],
            [InlineKeyboardButton("Дозаполнить", callback_data="car_edit:%d" % card_id)]]))
    raise ApplicationHandlerStop


def register(app):
    install()
    app.add_handler(CallbackQueryHandler(save, pattern=r"^ai_ok$"), group=-1)
    log.info("ai_filter подключён")
